import sys

# Increase recursion depth for deep VPS structures
sys.setrecursionlimit(10000)

def count_distinct_parenthesis_sequences(n: int, s: str) -> int:
    MOD = 998244353

    memo_can = {}
    memo_count = {}

    # Precompute factorials and their inverses
    fact = [1] * (n + 1)
    inv_fact = [1] * (n + 1)
    for i in range(1, n + 1):
        fact[i] = (fact[i-1] * i) % MOD

    inv_fact[n] = pow(fact[n], MOD - 2, MOD)
    for i in range(n - 1, -1, -1):
        inv_fact[i] = (inv_fact[i+1] * (i + 1)) % MOD

    def get_canonical(s):
        if not s:
            return ""
        if s in memo_can:
            return memo_can[s]

        primitives = []
        balance = 0
        start = 0
        for i, char in enumerate(s):
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance == 0:
                p = s[start:i+1]
                inner = p[1:-1]
                primitives.append('(' + get_canonical(inner) + ')')
                start = i + 1

        primitives.sort()
        res = "".join(primitives)
        memo_can[s] = res
        return res

    def count_equivalent(s):
        # s is assumed to be in canonical form
        if not s:
            return 1
        if s in memo_count:
            return memo_count[s]

        primitives = []
        balance = 0
        start = 0
        for i, char in enumerate(s):
            if char == '(':
                balance += 1
            else:
                balance -= 1
            if balance == 0:
                p = s[start:i+1]
                primitives.append(p)
                start = i + 1

        counts = {}
        for p in primitives:
            counts[p] = counts.get(p, 0) + 1

        k = len(primitives)
        res = fact[k]
        for p, count in counts.items():
            res = res * inv_fact[count] % MOD
            inner = p[1:-1]
            res = res * pow(count_equivalent(inner), count, MOD) % MOD

        memo_count[s] = res
        return res

    can_s = get_canonical(s)
    return count_equivalent(can_s)

