import functools
import sys
from typing import List

def card_game_winner(n: int, m: int, l: int, takahashi_cards: List[int], aoki_cards: List[int], table_cards: List[int]) -> str:
    # Increase recursion limit for deeper game trees
    sys.setrecursionlimit(5000)

    @functools.lru_cache(None)
    def can_win(t_h, a_h, tbl, turn):
        if turn == 0: # Takahashi's turn
            if not t_h:
                return False

            for i in range(len(t_h)):
                x = t_h[i]
                # Option 1: Take nothing
                new_t_h_none = t_h[:i] + t_h[i+1:]
                new_tbl_none = tuple(sorted(tbl + (x,)))
                if not can_win(new_t_h_none, a_h, new_tbl_none, 1):
                    return True

                # Option 2: Take y < x
                for j in range(len(tbl)):
                    y = tbl[j]
                    if y < x:
                        new_t_h_y = tuple(sorted(t_h[:i] + t_h[i+1:] + (y,)))
                        new_tbl_y = tuple(sorted(tbl[:j] + tbl[j+1:] + (x,)))
                        if not can_win(new_t_h_y, a_h, new_tbl_y, 1):
                            return True
            return False
        else: # Aoki's turn
            if not a_h:
                return False

            for i in range(len(a_h)):
                x = a_h[i]
                # Option 1: Take nothing
                new_a_h_none = a_h[:i] + a_h[i+1:]
                new_tbl_none = tuple(sorted(tbl + (x,)))
                if not can_win(t_h, new_a_h_none, new_tbl_none, 0):
                    return True

                # Option 2: Take y < x
                for j in range(len(tbl)):
                    y = tbl[j]
                    if y < x:
                        new_a_h_y = tuple(sorted(a_h[:i] + a_h[i+1:] + (y,)))
                        new_tbl_y = tuple(sorted(tbl[:j] + tbl[j+1:] + (x,)))
                        if not can_win(t_h, new_a_h_y, new_tbl_y, 0):
                            return True
            return False

    t_hand_tuple = tuple(sorted(takahashi_cards))
    a_hand_tuple = tuple(sorted(aoki_cards))
    table_tuple = tuple(sorted(table_cards))

    return "Takahashi" if can_win(t_hand_tuple, a_hand_tuple, table_tuple, 0) else "Aoki"

from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    used = [False] * n
    grid_cells = [[False] * w for _ in range(h)]

    def can_sum_to(areas, target):
        reachable = {0}
        for a in areas:
            reachable |= {x + a for x in list(reachable)}
        return target in reachable

    def search():
        start = None
        empty = 0
        for r in range(h):
            for c in range(w):
                if not grid_cells[r][c]:
                    if start is None:
                        start = (r, c)
                    empty += 1
        if start is None:
            return True
        r, c = start
        remaining = [tiles[i][0] * tiles[i][1] for i in range(n) if not used[i]]
        if not can_sum_to(remaining, empty):
            return False
        tried = set()
        for i in range(n):
            if used[i]:
                continue
            a, b = tiles[i]
            key = (a, b) if a <= b else (b, a)
            if key in tried:
                continue
            tried.add(key)
            for da, db in ((a, b), (b, a)):
                if da > h - r or db > w - c:
                    continue
                if any(grid_cells[rr][cc] for rr in range(r, r + da) for cc in range(c, c + db)):
                    continue
                for rr in range(r, r + da):
                    for cc in range(c, c + db):
                        grid_cells[rr][cc] = True
                used[i] = True
                if search():
                    return True
                used[i] = False
                for rr in range(r, r + da):
                    for cc in range(c, c + db):
                        grid_cells[rr][cc] = False
        return False

    return search()

