import sys
from collections import deque

def count_distinct_parenthesis_sequences(n: int, s: str) -> int:
    MOD = 998244353

    def is_vps(sub):
        bal = 0
        for char in sub:
            if char == '(': bal += 1
            else: bal -= 1
            if bal < 0: return False
        return bal == 0

    def mirror(sub):
        res = []
        for char in reversed(sub):
            res.append(')' if char == '(' else '(')
        return "".join(res)

    visited = {s}
    queue = deque([s])

    while queue:
        curr = queue.popleft()
        for i in range(n):
            for j in range(i + 2, n + 1, 2):
                sub = curr[i:j]
                if is_vps(sub):
                    m = mirror(sub)
                    next_s = curr[:i] + m + curr[j:]
                    if next_s not in visited:
                        visited.add(next_s)
                        queue.append(next_s)

    return len(visited) % MOD

