def count_good_sequences(N: int, M: int) -> int:
    MOD = 998244353

    if N == 0:
        return 0

    def get_dM(e):
        res = 1
        for i in range(1, e + 1):
            res = (res * (M - 1 + i)) % MOD
            res = (res * pow(i, MOD - 2, MOD)) % MOD
        return res

    def get_g_val(p, e):
        val = get_dM(e)
        if p == 3:
            return val
        if p % 3 == 1:
            return val if e % 3 != 2 else 0
        if p % 3 == 2:
            return val if e % 2 == 0 else 0
        return 0

    def get_h_val(p, e):
        return get_dM(e)

    def solve_sum(N, is_not_good):
        if N == 0: return 0
        sqrt_N = int(N**0.5)
        primes = []
        is_prime = [True] * (sqrt_N + 1)
        for p in range(2, sqrt_N + 1):
            if is_prime[p]:
                primes.append(p)
                for i in range(p * p, sqrt_N + 1, p):
                    is_prime[i] = False

        values = []
        i = 1
        while i <= N:
            val = N // i
            values.append(val)
            i = N // val + 1

        idx1 = [0] * (sqrt_N + 1)
        idx2 = [0] * (sqrt_N + 1)
        for i, v in enumerate(values):
            if v <= sqrt_N:
                idx1[v] = i
            else:
                idx2[N // v] = i

        def get_idx(v):
            return idx1[v] if v <= sqrt_N else idx2[N // v]

        s0 = [(v - 1) % MOD for v in values]
        s1 = [((v - 1) // 3) % MOD for v in values]
        s2 = [((v + 1) // 3) % MOD for v in values]

        for p in primes:
            p_sq = p * p
            if p == 3:
                sp0 = s0[get_idx(p - 1)]
                for i, v in enumerate(values):
                    if v < p_sq: break
                    s0[i] = (s0[i] - (s0[get_idx(v // p)] - sp0)) % MOD
                continue

            sp0 = s0[get_idx(p - 1)]
            sp1 = s1[get_idx(p - 1)]
            sp2 = s2[get_idx(p - 1)]
            p_mod = p % 3
            for i, v in enumerate(values):
                if v < p_sq: break
                s0[i] = (s0[i] - (s0[get_idx(v // p)] - sp0)) % MOD
                if p_mod == 1:
                    s1[i] = (s1[i] - (s1[get_idx(v // p)] - sp1)) % MOD
                    s2[i] = (s2[i] - (s2[get_idx(v // p)] - sp2)) % MOD
                else:
                    s1[i] = (s1[i] - (s2[get_idx(v // p)] - sp2)) % MOD
                    s2[i] = (s2[i] - (s1[get_idx(v // p)] - sp1)) % MOD

        def G_prime(v_idx):
            if not is_not_good:
                return (s0[v_idx] * M) % MOD
            else:
                return ((s0[v_idx] - s2[v_idx]) * M) % MOD

        def S_recursive(v, j):
            if v <= 1 or (j <= len(primes) and primes[j-1] > v):
                return 0

            p_j_minus_1 = primes[j-2] if j > 1 else 1
            res = (G_prime(get_idx(v)) - G_prime(get_idx(p_j_minus_1))) % MOD

            for k in range(j, len(primes) + 1):
                p = primes[k-1]
                if p * p > v: break
                p_e = p
                for e in range(1, 40):
                    if p_e * p > v: break
                    val_e = get_h_val(p, e) if not is_not_good else get_g_val(p, e)
                    val_e_plus_1 = get_h_val(p, e + 1) if not is_not_good else get_g_val(p, e + 1)
                    res = (res + val_e * S_recursive(v // p_e, k + 1) + val_e_plus_1) % MOD
                    p_e *= p
            return res % MOD

        return S_recursive(N, 1)

    total = (solve_sum(N, False) + 1) % MOD
    not_good = (solve_sum(N, True) + 1) % MOD
    return (total - not_good + MOD) % MOD

from collections import deque

def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    if s.count('B') != t.count('B'):
        return -1

    start_state = s + 'EE'
    target_state = t + 'EE'

    if start_state == target_state:
        return 0

    queue = deque([start_state])
    visited = {start_state: 0}

    while queue:
        u = queue.popleft()
        dist = visited[u]

        # Find empty cells
        empty_cells = [i for i, char in enumerate(u) if char == 'E']
        e1, e2 = empty_cells

        # Try moving adjacent stones
        for i in range(n + 1):
            if i + 1 < n + 2:
                if u[i] != 'E' and u[i+1] != 'E':
                    # Move stones at i and i+1 to e1 and e2
                    v_list = list(u)
                    v_list[i] = 'E'
                    v_list[i+1] = 'E'
                    v_list[e1] = u[i]
                    v_list[e2] = u[i+1]
                    v = "".join(v_list)

                    if v == target_state:
                        return dist + 1

                    if v not in visited:
                        visited[v] = dist + 1
                        queue.append(v)

    return -1

