def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    if s.count('B') != t.count('B'):
        return -1

    start_state = s + 'EE'
    target_state = t + 'EE'

    if start_state == target_state:
        return 0

    queue = deque([(start_state, 0)])
    visited = {start_state}

    while queue:
        u, dist = queue.popleft()

        # Find empty cells
        e1, e2 = -1, -1
        for i in range(n + 2):
            if u[i] == 'E':
                if e1 == -1:
                    e1 = i
                else:
                    e2 = i
                    break

        # Try moving adjacent stones
        u_list = list(u)
        for i in range(n + 1):
            if u_list[i] != 'E' and u_list[i+1] != 'E':
                # Move stones at i and i+1 to e1 and e2
                v_list = u_list[:]
                v_list[i] = 'E'
                v_list[i+1] = 'E'
                v_list[e1] = u_list[i]
                v_list[e2] = u_list[i+1]
                v = "".join(v_list)

                if v == target_state:
                    return dist + 1

                if v not in visited:
                    visited.add(v)
                    queue.append((v, dist + 1))

    return -1

