from collections import deque

def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    if s.count('B') != t.count('B'):
        return -1

    start = s + 'EE'
    if s == t:
        return 0

    queue = deque([(start, 0)])
    visited = {start}

    while queue:
        u, dist = queue.popleft()

        e = [i for i, c in enumerate(u) if c == 'E']
        e1, e2 = e[0], e[1]

        for i in range(n + 1):
            if u[i] != 'E' and u[i+1] != 'E':
                v_list = list(u)
                v_list[i] = 'E'
                v_list[i+1] = 'E'
                v_list[e1] = u[i]
                v_list[e2] = u[i+1]
                v = "".join(v_list)

                if v.replace('E', '') == t:
                    return dist + 1
                if v not in visited:
                    visited.add(v)
                    queue.append((v, dist + 1))
    return -1

