from typing import List, Tuple


def can_tile_grid(n: int, h: int, w: int, tiles: List[Tuple[int, int]]) -> bool:
    """ Determine if it's possible to place rectangular tiles on an H×W grid such that:
    - Every cell is covered by exactly one tile
    - Tiles can be rotated (so a 2×3 tile can be placed as 3×2)
    - Some tiles may remain unused
    - Tiles must be aligned with grid cells and cannot extend outside

    Args:
        n: Number of available tiles (1 ≤ n ≤ 7)
        h: Height of the grid (1 ≤ h ≤ 10)
        w: Width of the grid (1 ≤ w ≤ 10)
        tiles: List of (a, b) tuples where tile i has dimensions a×b (1 ≤ a, b ≤ 10)

    Returns:
        True if the grid can be perfectly tiled, False otherwise

    >>> can_tile_grid(5, 5, 5, [(1, 1), (3, 3), (4, 4), (2, 3), (2, 5)])
    True
    >>> can_tile_grid(1, 1, 2, [(2, 3)])
    False
    >>> can_tile_grid(1, 2, 2, [(1, 1)])
    False
    """
    grid = [[False for _ in range(w)] for _ in range(h)]
    used = [False] * n

    def solve():
        # Find the first empty cell
        r, c = -1, -1
        for i in range(h):
            for j in range(w):
                if not grid[i][j]:
                    r, c = i, j
                    break
            if r != -1:
                break

        if r == -1:
            return True

        # Try placing each available tile
        for i in range(n):
            if not used[i]:
                # Try both orientations
                tile_dims = tiles[i]
                # Use a set to avoid duplicate rotations for square tiles
                orientations = {tile_dims, (tile_dims[1], tile_dims[0])}
                for a, b in orientations:
                    # Check if tile fits
                    if r + a <= h and c + b <= w:
                        # Check if all cells in the rectangle are empty
                        possible = True
                        for dr in range(a):
                            for dc in range(b):
                                if grid[r + dr][c + dc]:
                                    possible = False
                                    break
                            if not possible:
                                break

                        if possible:
                            # Place tile
                            for dr in range(a):
                                for dc in range(b):
                                    grid[r + dr][c + dc] = True
                            used[i] = True

                            if solve():
                                return True

                            # Backtrack
                            used[i] = False
                            for dr in range(a):
                                for dc in range(b):
                                    grid[r + dr][c + dc] = False
        return False

    # Initial area check
    total_tile_area = sum(a * b for a, b in tiles)
    if total_tile_area < h * w:
        return False

    return solve()

