    # Transpose if W > H to ensure W is the smaller dimension
    # We need to store original H, W for the special case check, 
    # but the special case check is already done.

    orig_H, orig_W = H, W
    orig_grid = list(grid)

    if W > H:
        new_grid = [['?' for _ in range(H)] for _ in range(W)]
        for r in range(H):
