    A positive integer is called beautiful if the product of its digits is divisible by the sum of its digits.
    """

    def count_upto(X):
        if X == 0:
            return 0

        sX = str(X)
        n = len(sX)

        # 1. Count numbers in [1, X] with no 0 digits
        memo_no_zero = {}
        def get_no_zero(idx, is_less, is_started):
            state = (idx, is_less, is_started)
            if state in memo_no_zero:
                return memo_no_zero[state]

            if idx == n:
                return 1 if is_started else 0

            res = 0
            limit = int(sX[idx]) if not is_less else 9

            # Option 1: digit is 0
            if not is_started:
                # Leading zero
                res += get_no_zero(idx + 1, is_less or (0 < limit), False)
            else:
                # Not a leading zero, but we want NO 0 digits
                pass

            # Option 2: digit is 1-9
            for d in range(1, limit + 1):
                res += get_no_zero(idx + 1, is_less or (d < limit), True)

            # To handle digits 1-9 when limit is not reached
            if is_less:
                # We already covered 1..limit. Now we need to cover limit+1..9
                # Wait, the loop range(1, limit + 1) only goes up to limit.
                # If is_less is true, the limit is 9, so range(1, 10) covers all.
                pass

            # Correcting the loop for is_less:
            # If not is_less, we can go from 1 to limit.
            # If is_less, we can go from 1 to 9.

            # Let's rewrite the loop
            return res

        # Redoing get_no_zero more cleanly
        memo_no_zero = {}
        def get_no_zero_clean(idx, is_less, is_started):
            state = (idx, is_less, is_started)
            if state in memo_no_zero:
                return memo_no_zero[state]

            if idx == n:
                return 1 if is_started else 0

            res = 0
            limit = int(sX[idx]) if not is_less else 9

            # Case 1: digit is 0
            if not is_started:
                res += get_no_zero_clean(idx + 1, is_less or (0 < limit), False)

            # Case 2: digit is 1-9
            for d in range(1, limit + 1):
                res += get_no_zero_clean(idx + 1, is_less or (d < limit), True)

            memo_no_zero[state] = res
            return res

        no_zero_count = get_no_zero_clean(0, False, False)
        total_with_zero = X - no_zero_count

        # 2. Count numbers in [1, X] with no 0 digits, sum S, and prod % S == 0
        total_no_zero_beautiful = 0

        # We can iterate over S from 1 to 9 * 9 = 81
        # For each S, we use digit DP
        for S in range(1, 82):
            memo_s = {}
            def get_beautiful(idx, current_sum, current_prod_mod, is_less, is_started):
                if current_sum > S:
                    return 0

                state = (idx, current_sum, current_prod_mod, is_less, is_started)
                if state in memo_s:
                    return memo_s[state]

                if idx == n:
                    return 1 if (is_started and current_sum == S and current_prod_mod == 0) else 0

                res = 0
                limit = int(sX[idx]) if not is_less else 9

                # Case 1: digit is 0
                if not is_started:
                    res += get_beautiful(idx + 1, 0, 0, is_less or (0 < limit), False)

                # Case 2: digit is 1-9
                for d in range(1, limit + 1):
                    new_sum = current_sum + d
                    if new_sum <= S:
                        new_prod_mod = (current_prod_mod * d) % S if is_started else d % S
                        res += get_beautiful(idx + 1, new_sum, new_prod_mod, is_less or (d < limit), True)

                memo_s[state] = res
                return res

            total_no_zero_beautiful += get_beautiful(0, 0, 0, False, False)

        return total_with_zero + total_no_zero_beautiful

