    for u, v in edges:
        adj[u].append(v)
        adj[v].append(u)

    parent = [0] * (n + 1)
    order = []
    stack = [1]
    parent[1] = -1
    while stack:
        u = stack.pop()
        order.append(u)
        for v in adj[u]:
            if parent[v] == 0:
                parent[v] = u
                stack.append(v)

    h_down = [1] * (n + 1)
    for u in reversed(order):
        children_h = [h_down[v] for v in adj[u] if v != parent[u]]
        if len(children_h) >= 3:
            top3 = heapq.nlargest(3, children_h)
            h_down[u] = 1 + sum(top3)
        else:
            h_down[u] = 1

    h_up = [1] * (n + 1)
    for u in order:
        children = [v for v in adj[u] if v != parent[u]]

        branches = []
        if parent[u] != 0:
            branches.append((h_up[u], -1))
        for v in children:
            branches.append((h_down[v], v))

        branches.sort(key=lambda x: x[0], reverse=True)
        top4 = branches[:4]

        for v in children:
            others = [val for val, vid in top4 if vid != v]
            if len(others) >= 3:
                h_up[v] = 1 + sum(others[:3])
            else:
                h_up[v] = 1

    max_size = -1
    for u in range(1, n + 1):
        all_h = []
        if parent[u] != 0:
            all_h.append(h_up[u])
        for v in adj[u]:
            if v != parent[u]:
                all_h.append(h_down[v])

        if len(all_h) >= 4:
            top4 = heapq.nlargest(4, all_h)
            max_size = max(max_size, 1 + sum(top4))

    return max_size

