from itertools import combinations_with_replacement, permutations
from math import factorial

def count_k_palindromic_numbers(n: int, k: int) -> int:
    """ Count the number of good integers containing exactly n digits.

    An integer x is called k-palindromic if:
    - x is a palindrome (reads the same forwards and backwards)
    - x is divisible by k

    An integer is called good if its digits can be rearranged to form a k-palindromic integer.

    Note: Integers must not have leading zeros, neither before nor after rearrangement.

    Args:
        n: The number of digits (1 <= n <= 10)
        k: The divisor for k-palindromic property (1 <= k <= 9)

    Returns:
        The count of good integers with exactly n digits
    """

    def count_perms_no_leading_zero(counts):
        n_total = sum(counts)
        denom = 1
        for c in counts:
            denom *= factorial(c)
        total_perms = factorial(n_total) // denom
        if counts[0] == 0:
            return total_perms
        leading_zero_perms = (total_perms * counts[0]) // n_total
        return total_perms - leading_zero_perms

    total_good_count = 0
    half_n = n // 2

    # To avoid processing the same multiset multiple times
    processed_multisets = set()

    # Generate all possible multisets H of size half_n
    for h_tuple in combinations_with_replacement(range(10), half_n):
        if n % 2 == 0:
            # Case: n is even
            counts = [0] * 10
            for d in h_tuple:
                counts[d] += 2

            s_tuple = tuple(counts)
            if s_tuple in processed_multisets:
                continue
            processed_multisets.add(s_tuple)

            # Check if S can form a k-palindromic integer
            is_good = False
            # Try all distinct permutations p of h_tuple
            for p in set(permutations(h_tuple)):
                if n > 0 and p[0] == 0:
                    continue

                # Construct palindrome P
                val = 0
                for digit in p:
                    val = val * 10 + digit
                for digit in reversed(p):
                    val = val * 10 + digit

                if val % k == 0:
                    is_good = True
                    break

            if is_good:
                total_good_count += count_perms_no_leading_zero(counts)

        else:
            # Case: n is odd
            for m in range(10):
                counts = [0] * 10
                for d in h_tuple:
                    counts[d] += 2
                counts[m] += 1

                s_tuple = tuple(counts)
                if s_tuple in processed_multisets:
                    continue
                processed_multisets.add(s_tuple)

                # Check if S can form a k-palindromic integer
                is_good = False
                if half_n == 0:
                    # Palindrome is just m
                    if m != 0 and m % k == 0:
                        is_good = True
                else:
                    for p in set(permutations(h_tuple)):
                        if p[0] == 0:
                            continue

                        val = 0
                        for digit in p:
                            val = val * 10 + digit
                        val = val * 10 + m
                        for digit in reversed(p):
                            val = val * 10 + digit

                        if val % k == 0:
                            is_good = True
                            break

                if is_good:
                    total_good_count += count_perms_no_leading_zero(counts)

    return total_good_count

from functools import lru_cache

def solve(n, k):
    if n <= 0:
        return 0
    s = str(n)
    L = len(s)

    @lru_cache(None)
    def dp(pos, diff, rem, is_less, is_started):
        if pos == L:
            return 1 if is_started and diff == 0 and rem == 0 else 0

        res = 0
        limit = int(s[pos]) if not is_less else 9

        for d in range(limit + 1):
            next_is_less = is_less or (d < limit)
            next_is_started = is_started or (d > 0)

            if not next_is_started:
                res += dp(pos + 1, 0, 0, next_is_less, False)
            else:
                next_diff = diff + (1 if d % 2 == 0 else -1)
                next_rem = (rem * 10 + d) % k
                res += dp(pos + 1, next_diff, next_rem, next_is_less, True)

        return res

    return dp(0, 0, 0, False, False)

def count_beautiful_integers(low: int, high: int, k: int) -> int:
    """ Count the number of beautiful integers in the range [low, high].

    A number is beautiful if it meets both conditions:
    1. The count of even digits equals the count of odd digits
    2. The number is divisible by k

    Args:
        low: Lower bound of the range (inclusive), 0 < low <= high <= 10^9
        high: Upper bound of the range (inclusive)
        k: Divisor to check, 0 < k <= 20

    Returns:
        The count of beautiful integers in the given range
    """
    return solve(high, k) - solve(low - 1, k)

def sum_of_scores(n: int, m: int) -> int:
    """ Calculate the sum of scores of all good sequences modulo 998244353.

    A good sequence is an integer sequence of length between 1 and n (inclusive),
    where each element is between 1 and m (inclusive).

    The score of a good sequence is the number of positive divisors of X,
    where X is the product of all elements in the sequence.

    The function computes the sum of scores of all possible good sequences.
    There are sum(m^k for k in range(1, n+1)) such sequences in total.

    Args:
        n: Maximum length of sequences (1 <= n <= 10^18)
        m: Maximum value of elements (1 <= m <= 16)

    Returns:
        The sum of all scores modulo 998244353
    """
    MOD = 998244353

    if m == 1:
        return n % MOD

    primes = [2, 3, 5, 7, 11, 13]
    num_primes = len(primes)

    def get_v_p(x, p):
        count = 0
        while x > 0 and x % p == 0:
            count += 1
            x //= p
        return count

    # W[S] = sum_{x=1}^m prod_{p_i in S} v_{p_i}(x)
    W = [0] * (1 << num_primes)
    for mask in range(1 << num_primes):
        s_val = 0
        for x in range(1, m + 1):
            prod = 1
            for i in range(num_primes):
                if (mask >> i) & 1:
                    prod *= get_v_p(x, primes[i])
            s_val += prod
        W[mask] = s_val % MOD

    size = 1 << num_primes

    def mat_mul(A, B):
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            row_A = A[i]
            for k in range(size):
                val_A = row_A[k]
                if val_A == 0: continue
                row_B = B[k]
                for j in range(size):
                    C[i][j] = (C[i][j] + val_A * row_B[j]) % MOD
        return C

    def mat_add(A, B):
        C = [[0] * size for _ in range(size)]
        for i in range(size):
            for j in range(size):
                C[i][j] = (A[i][j] + B[i][j]) % MOD
        return C

    M_prime = [[0] * size for _ in range(size)]
    for s in range(size):
        for t in range(size):
            if (s & t) == t:
                M_prime[s][t] = W[s ^ t]

    def compute_sum_and_pow(k):
        if k == 1:
            return M_prime, M_prime

        if k % 2 == 0:
            S_half, P_half = compute_sum_and_pow(k // 2)
            # S_k = S_{k/2} + P_{k/2} * S_{k/2} = (I + P_{k/2}) * S_{k/2}
            I_plus_P = [row[:] for row in P_half]
            for i in range(size):
                I_plus_P[i][i] = (I_plus_P[i][i] + 1) % MOD

            S_k = mat_mul(I_plus_P, S_half)
            P_k = mat_mul(P_half, P_half)
            return S_k, P_k
        else:
            S_prev, P_prev = compute_sum_and_pow(k - 1)
            P_k = mat_mul(P_prev, M_prime)
            S_k = mat_add(S_prev, P_k)
            return S_k, P_k

    S_n, _ = compute_sum_and_pow(n)

    # Result is sum of all elements in the first column of S_n
    ans = 0
    for i in range(size):
        ans = (ans + S_n[i][0]) % MOD

    return ans

