            B[s][t] = M_prime[s][t]

    # Bottom row: B[size][t] = sum_s M_prime[s][t]
    for t in range(size):
        col_sum = 0
        for s in range(size):
            col_sum = (col_sum + M_prime[s][t]) % MOD
        B[size][t] = col_sum

    B[size][size] = 1

    def mat_pow(A, p, sz):
        res = [[0] * sz for _ in range(sz)]
        for i in range(sz):
            res[i][i] = 1
        while p > 0:
            if p % 2 == 1:
                res = mat_mul(res, A, sz)
            A = mat_mul(A, A, sz)
            p //= 2
        return res

    B_n = mat_pow(B, n, B_size)

    # Result is (B^n)_{size, 0}
    return B_n[size][0]

