from collections import deque

def min_operations_to_rearrange(n: int, s: str, t: str) -> int:
    if s.count('B') != t.count('B'):
        return -1

    if s == t:
        return 0

    start_state = s + 'EE'
    target_state = t + 'EE'

    queue = deque([(start_state, 0)])
    visited = {start_state}

    while queue:
        u, dist = queue.popleft()

        e1 = u.find('E')
        e2 = u.rfind('E')

        for i in range(n + 1):
            if u[i] != 'E' and u[i+1] != 'E':
                v_list = list(u)
                v_list[i] = 'E'
                v_list[i+1] = 'E'
                v_list[e1] = u[i]
                v_list[e2] = u[i+1]
                v = "".join(v_list)

                if v == target_state:
                    return dist + 1

                if v not in visited:
                    visited.add(v)
                    queue.append((v, dist + 1))

    return -1

